<script setup>
import {ref,computed,onMounted,onBeforeUnmount,nextTick,watch,inject} from 'vue';import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';import {get,api} from '../api/client';import SourceComparison from '../components/SourceComparison.vue';import FoodRecordForm from '../components/FoodRecordForm.vue';import FoodRecordTable from '../components/FoodRecordTable.vue';
import {reviewStatus,reviewName,draftSnapshot,filterReviewItems,nextPendingItem,requiredReviewFields,reviewErrorMessage} from '../utils/reviewJourney';
const route=useRoute(),router=useRouter(),user=inject('user');const sourceReady=ref(false),report=ref(null),doc=ref(null),run=ref(null),suppliers=ref([]),products=ref([]),selected=ref(''),draft=ref({}),reason=ref(''),error=ref(''),busy=ref(false),message=ref(''),proposals=ref([]),jobs=ref([]);
const manualOpen=ref(false),manualPage=ref(0);const manualIds=computed(()=>(report.value?.manual_evidence_ids||[]).slice(manualPage.value*10,manualPage.value*10+10));
const filter=ref('all'),query=ref(''),showTable=ref(false),stage=ref('review'),mobilePane=ref('fields'),savedSnapshot=ref(''),leaveTarget=ref(null),discardButton=ref(null);
const pending=computed(()=>Math.max(0,(report.value?.events.length||0)-confirmed.value-skipped.value));
const visibleItems=computed(()=>filterReviewItems(report.value?.events||[],filter.value,query.value));
const currentIndex=computed(()=>report.value?.events.findIndex(e=>e.id===selected.value)??-1);
const dirty=computed(()=>!!active.value&&draftSnapshot(draft.value,reason.value)!==savedSnapshot.value);
const missing=computed(()=>requiredReviewFields(draft.value));
const applied=computed(()=>proposals.value.length>0&&proposals.value.every(p=>p.summary.status==='applied'));
const statusLabel=s=>({pending:'검토 대기',confirmed:'확인 완료',skipped:'제외'}[s]||s);
function itemSpec(item){return (item.review?.fields?.food_record||item.food_record)?.specification?.original_text||(item.review?.fields||item).spec||'규격 미기재'}
async function selectItem(id){if(!id||id===selected.value||busy.value)return;if(dirty.value&&!locked.value){leaveTarget.value=id;await nextTick();discardButton.value?.focus();return}selected.value=id;error.value='';mobilePane.value='fields'}
function trapDialogFocus(event){const buttons=event.currentTarget.querySelectorAll('button');const first=buttons[0],last=buttons[buttons.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
function discardAndMove(){const id=leaveTarget.value;leaveTarget.value=null;resetDraft();if(id==='summary')stage.value='summary';else selected.value=id;error.value=''}
async function openSummary(){if(busy.value)return;if(dirty.value&&!locked.value){leaveTarget.value='summary';await nextTick();discardButton.value?.focus();return}stage.value='summary';error.value=''}
function beforeUnload(e){if(dirty.value&&!locked.value){e.preventDefault();e.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload));
onBeforeRouteLeave(()=>!dirty.value||locked.value||window.confirm('저장하지 않은 수정 내용이 있습니다. 이 화면을 나가시겠어요?'));
onBeforeRouteUpdate(()=>!dirty.value||locked.value||window.confirm('저장하지 않은 수정 내용이 있습니다. 다른 분석 결과로 이동할까요?'));
const existing=ref(null);let existingRequest=0;watch(()=>draft.value.product_id,async id=>{const request=++existingRequest;existing.value=null;if(!id)return;try{const [detail,prices]=await Promise.all([get('/products/'+id),get('/prices?product_id='+id+'&include_scheduled=true')]);if(request===existingRequest)existing.value={detail,prices:prices.items}}catch{}});
const names={food_profile:'식품 정보 등록·수정',price:'단가 변경',temporarily_unavailable:'공급 일시중단',supply_ended:'공급 종료',discontinued:'제조 단종',available:'공급 가능',substitution:'대체품',new_product:'신제품'};const fields=['kind','product_name','spec','amount','quantity','unit','effective_from','effective_to','reason','replacements','price_basis','food_record'];
const canReview=computed(()=>user.value.roles.some(x=>['admin','reviewer'].includes(x)));const locked=computed(()=>proposals.value.some(p=>['approved','applying','applied','apply_failed'].includes(p.summary.status)));const active=computed(()=>report.value?.events.find(e=>e.id===selected.value));const confirmed=computed(()=>report.value?.events.filter(e=>e.review?.status==='confirmed').length||0);const skipped=computed(()=>report.value?.events.filter(e=>e.review?.status==='skipped').length||0);const changed=computed(()=>active.value&&fields.filter(k=>draft.value.kind==='price'||!['amount','quantity','unit','price_basis'].includes(k)).some(k=>JSON.stringify(draft.value[k]??null)!==JSON.stringify((active.value.ai_original||active.value)[k]??null)));
let approvalTimer,approvalDisposed=false;
async function refreshApproval(){const id=route.params.id;try{const latest=await Promise.all(proposals.value.map(p=>get('/proposals/'+p.summary.id)));if(!approvalDisposed&&route.params.id===id)proposals.value=latest}catch(e){if(!approvalDisposed)error.value=e.message}finally{clearTimeout(approvalTimer);if(!approvalDisposed&&proposals.value.some(p=>p.summary.status==='applying'))approvalTimer=setTimeout(refreshApproval,3000)}}
watch(()=>proposals.value.map(p=>p.summary.status).join(','),()=>{clearTimeout(approvalTimer);if(proposals.value.some(p=>p.summary.status==='applying'))approvalTimer=setTimeout(refreshApproval,3000)});
onBeforeUnmount(()=>{approvalDisposed=true;clearTimeout(approvalTimer)});
let loadRequest=0;
async function load(){const request=++loadRequest,id=route.params.id;try{
 const nextRun=await get('/analysis-runs/'+id);const rev=await get('/document-revisions/'+nextRun.document_revision_id);
 const [nextReport,nextDoc,nextSuppliers,nextProducts]=await Promise.all([get('/analysis-runs/'+id+'/report'),get('/documents/'+rev.document_id),get('/suppliers?limit=100'),get('/products?limit=100')]);
 const nextProposals=await Promise.all(nextReport.proposal_ids.map(pid=>get('/proposals/'+pid)));
 if(request!==loadRequest)return;
 run.value=nextRun;report.value=nextReport;doc.value=nextDoc;suppliers.value=nextSuppliers.items;products.value=nextProducts.items;proposals.value=nextProposals;
 if(nextProposals.some(p=>['applying','applied','approved'].includes(p.summary.status)))stage.value='summary';
 selected.value=nextReport.events.find(e=>reviewStatus(e)==='pending')?.id||nextReport.events[0]?.id||'';resetDraft();
}catch(e){if(request===loadRequest)error.value=e.message}}
watch(()=>route.params.id,()=>{report.value=null;proposals.value=[];selected.value='';sourceReady.value=false;stage.value='review';jobs.value=[];error.value='';load()});
onBeforeUnmount(()=>{loadRequest++});
function resetDraft(){const e=active.value;if(!e)return;const current=e.review?.fields||e;draft.value={...Object.fromEntries(fields.map(k=>[k,current[k]??null])),food_record:JSON.parse(JSON.stringify(current.food_record||e.food_record)),supplier_id:current.supplier_id||suppliers.value.find(s=>s.name===doc.value?.author_display_name)?.id||null,product_id:current.product_id||e.matched_product_id||null};reason.value=e.review?.reason||'';savedSnapshot.value=draftSnapshot(draft.value,reason.value)}
watch(selected,resetDraft);onMounted(load);
async function save(status){if(!active.value)return;busy.value=true;error.value='';try{if(status==='confirmed'){if(!draft.value.food_record?.food_name?.trim())throw new Error('식품명을 확인해 주세요.');if(!['food_profile','new_product'].includes(draft.value.kind)){if(!draft.value.effective_from)throw new Error('적용 시작일을 입력하거나 이번 반영에서 제외해 주세요.');if(!draft.value.food_record.company_name)throw new Error('업체를 입력해 주세요.')}}draft.value.product_name=draft.value.food_record.food_name;draft.value.spec=draft.value.food_record.specification.original_text;draft.value.supplier_id=draft.value.food_record.company_id;if(changed.value&&!reason.value.trim()&&status==='confirmed')throw new Error('수정한 이유를 간단히 남겨 주세요.');const body={version:report.value.version,status,fields:draft.value,reason:reason.value.trim()||(status==='skipped'?'이번 반영에서 제외':'원문과 표준 식품 정보를 대조해 확인')};const r=await api('/analysis-runs/'+route.params.id+'/items/'+active.value.id,{method:'PATCH',body});report.value=r.data;proposals.value=[];const next=nextPendingItem(report.value.events,selected.value);message.value=status==='skipped'?'이 항목을 반영 대상에서 제외했습니다.':'원문 대조 결과를 저장했습니다. DB 반영은 아직 진행하지 않았습니다.';if(next)selected.value=next.id;resetDraft();if(!next)stage.value='summary'}catch(e){error.value=e.message}finally{busy.value=false}}
async function submitReviewed(){if(busy.value)return;busy.value=true;error.value='';try{const result=await api('/analysis-runs/'+route.params.id+'/approve',{method:'POST',body:{version:report.value.version}});report.value=result.data.report;jobs.value=result.data.jobs;proposals.value=await Promise.all(result.data.proposal_ids.map(id=>get('/proposals/'+id)));message.value='승인한 식품 정보의 DB 반영을 시작했습니다.'}catch(e){error.value=reviewErrorMessage(e)}finally{busy.value=false}}
const prepared=computed(()=>report.value?.review_prepared&&proposals.value.length&&proposals.value.every(p=>p.changes.every(ch=>ch.field_evidence.every(f=>f.origin==='reviewer'))));async function download(){try{const result=await api('/analysis-runs/'+route.params.id+'/review-export',{method:'POST',body:{}});report.value.export_asset_id=result.data.export_asset_id;const a=await get('/assets/'+report.value.export_asset_id+'/access');window.open(a.url,'_blank','noopener')}catch(e){error.value=e.message}}
</script>
<template>
<div class="review-journey">
  <header class="journey-header">
    <div><RouterLink to="/reviews" class="back-link">← 검수함</RouterLink><h1>식품 정보 검토</h1><p class="muted">원문과 비교하고, 확인한 정보만 식품 장부에 반영하세요.</p></div>
    <RouterLink v-if="doc" :to="'/documents/'+doc.id" class="secondary">자료 정보 ↗</RouterLink>
  </header>
  <p v-if="error" class="error" role="alert">{{error}}</p>
  <p v-if="message" class="success" role="status">{{message}}</p>
  <template v-if="report">
    <aside v-if="canReview&&!locked&&report.consolidation?.version!=='food-consolidation-v4'" class="notice normalization-action"><div><b>원문에 있는데 비어 있는 정보가 있나요?</b><p>원본 표에서 원재료·함량·규격을 다시 정리합니다. 기존 검토 기록을 보존한 새 검토본을 만들며 추가 AI 호출은 없습니다.</p></div></aside>
    <p v-for="(warning,i) in report.warnings" :key="i" class="warning">{{warning}}</p>
    <details v-if="report.manual_evidence_ids?.length" class="panel unresolved-sources" @toggle="manualOpen=$event.target.open"><summary>자동으로 정리하지 못한 원문 {{report.manual_evidence_ids.length}}개 확인</summary><p>Agent가 확인을 요청했거나 상품 영역을 확정하지 못한 자료입니다. 아래 원문을 확인해 주세요.</p><SourceComparison v-if="manualOpen" :ids="manualIds"/><div class="row wrap"><button class="secondary" :disabled="manualPage===0" @click="manualPage--">이전 원문</button><span>{{manualPage+1}} / {{Math.ceil(report.manual_evidence_ids.length/10)}}</span><button class="secondary" :disabled="(manualPage+1)*10>=report.manual_evidence_ids.length" @click="manualPage++">다음 원문</button></div></details>
    <section class="journey-overview">
      <div class="document-context"><span class="context-label">검토 중인 자료</span><b>{{doc?.title}}</b><span v-if="locked" class="state-pill confirmed">{{applied?'DB 반영 완료':'승인·반영 단계'}}</span></div>
      <div class="journey-progress"><div><strong>{{confirmed+skipped}}</strong><span> / {{report.events.length}}개 검토 완료</span></div><span>{{pending ? '대기 '+pending+'개' : '모든 품목 검토 완료'}}</span></div>
      <progress :value="confirmed+skipped" :max="report.events.length||1" aria-label="품목 검토 진행률"/>
      <nav class="journey-steps" aria-label="검토 단계">
        <span class="done"><i>✓</i> 자료 분석</span><span class="step-line"/>
        <button :disabled="busy" :class="{current:stage==='review'}" :aria-current="stage==='review'?'step':undefined" @click="stage='review'"><i>2</i> 품목 검토</button><span class="step-line"/>
        <button :class="{current:stage==='summary'}" :aria-current="stage==='summary'?'step':undefined" @click="openSummary"><i>3</i> {{locked?'반영 내역':'반영 확인'}}</button>
      </nav>
    </section>
    <div v-if="report.latest_analysis_run_id&&report.latest_analysis_run_id!==route.params.id" class="warning">더 최근에 분석한 결과가 있습니다. <RouterLink :to="'/analysis-runs/'+report.latest_analysis_run_id+'/review'">최신 결과 보기 →</RouterLink></div>
    <div v-if="report.consolidation" class="notice small"><b>원문 후보 {{report.consolidation.input_events}}개 → 검토 항목 {{report.consolidation.review_items}}개</b><p>중복 근거는 품목별로 함께 연결했습니다. 업체·규격·가격·적용 기간이 충돌하는 항목은 별도로 남깁니다.</p><RouterLink v-if="report.consolidation.source_analysis_run_id" :to="'/analysis-runs/'+report.consolidation.source_analysis_run_id+'/review'">이전 추출 결과·검토 기록 보기 →</RouterLink></div>
    <div v-if="locked" class="locked-banner"><span><b>{{applied?'검토한 정보가 장부에 반영되었습니다.':'이 결과는 승인·반영 단계에 있습니다.'}}</b> 원문과 검토 내용을 조회할 수 있습니다.</span><RouterLink to="/products">식품 목록 →</RouterLink></div>

    <template v-if="stage==='review'&&report.events.length">
      <section class="item-selector" aria-label="검토 품목 선택">
        <div class="selector-toolbar"><h2>검토할 품목 <span>{{report.events.length}}</span></h2><button class="text-button" :aria-expanded="showTable" @click="showTable=!showTable">{{showTable?'전체 표 접기':'전체 표 보기 ↗'}}</button></div>
        <div class="selector-controls"><div class="status-filters" aria-label="검토 상태 필터"><button v-for="(label,key) in {all:'전체',pending:'대기',confirmed:'확인',skipped:'제외'}" :key="key" :aria-pressed="filter===key" :class="{active:filter===key}" @click="filter=key">{{label}} <span>{{key==='all'?report.events.length:key==='pending'?pending:key==='confirmed'?confirmed:skipped}}</span></button></div><input v-model="query" type="search" aria-label="품목 검색" placeholder="식품명·업체·규격 검색"></div>
        <div v-if="visibleItems.length" class="item-strip"><button v-for="item in visibleItems" :key="item.id" class="item-card" :class="{selected:selected===item.id}" :aria-pressed="selected===item.id" :disabled="busy" @click="selectItem(item.id)"><div><span class="state-dot" :class="reviewStatus(item)"/><span class="item-card-name">{{reviewName(item)}}</span><span v-if="selected===item.id" class="selected-mark">선택</span></div><small>{{itemSpec(item)}}</small><div><span class="state-pill" :class="reviewStatus(item)">{{statusLabel(reviewStatus(item))}}</span><span class="item-kind">{{names[(item.review?.fields||item).kind]}}</span></div></button></div>
        <p v-else class="filter-empty">조건에 맞는 품목이 없습니다. <button class="text-button" @click="filter='all';query=''">필터 초기화</button></p>
        <div v-if="showTable" class="all-items-table"><FoodRecordTable :rows="visibleItems" :selected="selected" @select="selectItem"/></div>
      </section>
      <div v-if="active" class="selected-context"><div><span class="context-label">선택한 품목 · {{currentIndex+1}} / {{report.events.length}}</span><h2>{{draft.food_record?.food_name||'식품명 확인 필요'}}</h2></div><div class="row"><button class="nav-button" aria-label="이전 품목" :disabled="busy||currentIndex<=0" @click="selectItem(report.events[currentIndex-1]?.id)">←</button><button class="nav-button" aria-label="다음 품목" :disabled="busy||currentIndex>=report.events.length-1" @click="selectItem(report.events[currentIndex+1]?.id)">→</button></div></div>
      <div class="mobile-pane-switch" aria-label="검토 화면 전환"><button :aria-pressed="mobilePane==='source'" @click="mobilePane='source'">원문 보기</button><button :aria-pressed="mobilePane==='fields'" @click="mobilePane='fields'">{{locked?'검토한 정보':'정보 확인·수정'}}</button></div>
      <div v-if="active" class="review-desk" :class="'mobile-'+mobilePane">
        <SourceComparison :ids="active.evidence_ids" @ready="sourceReady=$event"/>
        <section class="review-editor">
          <div class="desk-heading"><div><span class="context-label">{{locked?'저장된 검토 내용':'추출된 표준 정보'}}</span><h3>{{locked?'확인한 식품 정보':'확인하고 수정해 주세요'}}</h3></div><span class="state-pill" :class="dirty?'pending':reviewStatus(active)">{{dirty?'저장 전':statusLabel(reviewStatus(active))}}</span></div>
          <div class="editor-scroll" :key="selected">
            <div v-if="!locked&&active.review_reasons?.length" class="review-hints"><b>이 부분을 확인해 주세요</b><p v-for="hint in active.review_reasons" :key="hint">{{hint}}</p></div>
            <fieldset :disabled="busy||locked||!canReview" class="editor-fields">
              <label>어떤 정보인가요?<select v-model="draft.kind"><option v-for="(label,value) in names" :key="value" :value="value">{{label}}</option></select></label>
              <FoodRecordForm v-model="draft.food_record" :companies="suppliers" compact>
              <section class="change-fields" v-if="!['food_profile','new_product'].includes(draft.kind)"><h4>변경 내용</h4>
                <div v-if="draft.kind==='price'" class="price-grid"><label>단가(원)<input v-model="draft.amount" inputmode="decimal" aria-label="추출 단가"></label><label>기준 수량<input v-model="draft.quantity" inputmode="decimal" aria-label="가격 기준 수량"></label><label>단위<select v-model="draft.unit"><option :value="null">선택</option><option v-for="u in ['g','kg','ml','l','ea','bag','box','pack']" :key="u" :value="u">{{u}}</option></select></label><p class="muted">원문 추출값: {{(active.ai_original||active).amount??'미기재'}}원</p></div>
                <div class="two-col"><label>적용 시작일<input v-model="draft.effective_from" type="date" aria-label="추출 적용 시작일"></label><label>종료일 <span class="optional">선택</span><input v-model="draft.effective_to" type="date"></label></div>
                <label>원문에 적힌 사유<textarea v-model="draft.reason" rows="2" aria-label="추출 사유" placeholder="원문에 사유가 없으면 공란"></textarea></label>
              </section>
              </FoodRecordForm>
              <details class="db-matching"><summary>기존 식품 연결 <span>{{draft.product_id?'연결됨':'새 식품으로 등록'}}</span></summary><p class="small muted">이미 등록한 식품이라면 선택해 주세요.</p><label>기존 식품<select v-model="draft.product_id"><option :value="null">새 식품으로 등록</option><option v-for="p in products" :key="p.id" :value="p.id">{{p.name}}</option></select></label><div v-if="existing" class="notice small"><b>현재 DB · {{existing.detail.name}}</b><p>등록 규격: {{existing.detail.variants.map(v=>v.spec_original).join(' / ')}}</p><p v-for="p in existing.prices" :key="p.id">{{p.spec_label}} · {{Number(p.value.amount).toLocaleString()}}원 / {{p.value.quantity}}{{p.value.unit}} · {{p.period.effective_from}}부터</p><p v-if="!existing.prices.length">등록된 단가 없음</p></div></details>
              <label>검토 메모 <span class="optional">{{changed?'수정 사유를 남겨 주세요':'선택'}}</span><textarea v-model="reason" rows="2" placeholder="예: 원문에 표시된 규격으로 수정" aria-label="품목 검토 메모"></textarea></label>
